bool Gold(const void *actor, std::int64_t &raw) noexcept {
#if defined(_MSC_VER)
  __try {
#endif
    void *living = nullptr;
    std::memcpy(&living,
                static_cast<const std::byte *>(actor) +
                    ck3_12002::kWarCashCharacterLivingExtensionOffset,
                sizeof(living));
    // This is stock GetGold's legitimate zero for a missing extension.
    raw = 0;
    if (living != nullptr) {
      std::memcpy(&raw,
                  static_cast<const std::byte *>(living) +
                      ck3_12002::kWarCashCharacterGoldOffset,
                  sizeof(raw));
    }
    return true;

bool MonthlyFlow(const Bindings &bindings, void *actor,
                 std::int32_t actor_id, ActorResources &output) noexcept {
  output.gross_income_unavailable_reason = "war_cash_monthly_income_unavailable";
  output.total_expenses_unavailable_reason = "war_cash_monthly_total_expenses_unavailable";
  output.income_unavailable_reason = "war_cash_monthly_net_income_unavailable";
  if (bindings.monthly_income == nullptr ||
      bindings.expense_context_character == nullptr ||
      bindings.monthly_total_expenses == nullptr) return false;
#if defined(_MSC_VER)
  __try {
#endif
    // DF1C70's gold HUD writer uses this exact .3 native argument chain.
    void *context = bindings.expense_context_character(actor);
    if (context == nullptr || !ActorMatches(actor, actor_id)) return false;
    std::int64_t gross = 0;
    std::int64_t secondary_income = 0;
    if (bindings.monthly_income(&gross, actor, &secondary_income, nullptr) != &gross ||
        !ActorMatches(actor, actor_id)) return false;
    output.monthly_gross_income_raw = gross;
    output.gross_income_unavailable_reason.clear();
    std::int64_t expenses = 0;
    if (bindings.monthly_total_expenses(&expenses, actor, context,
                                      secondary_income, false, nullptr) != &expenses ||
        !ActorMatches(actor, actor_id)) return false;
    output.monthly_total_expenses_raw = expenses;
    output.total_expenses_unavailable_reason.clear();
    constexpr auto minimum = std::numeric_limits<std::int64_t>::min();
    constexpr auto maximum = std::numeric_limits<std::int64_t>::max();
    if ((expenses > 0 && gross < minimum + expenses) ||
        (expenses < 0 && gross > maximum + expenses)) {
      output.income_unavailable_reason = "war_cash_monthly_net_income_overflow";
      return false;
    }
    output.monthly_net_income_raw = gross - expenses;
    output.income_unavailable_reason.clear();

    // Read after the existing getters, on this same owning paused mailbox.
    // The raw helper does not invoke a native getter or create a callback record.
#if defined(XAR_ENABLE_WAR_PAYMENT_GENERIC_CONTEXT_12004)
    if(bindings.current_raw_context_enabled) {
      CurrentRawContext raw{};
      raw.character=reinterpret_cast<std::uintptr_t>(actor);
      raw.character_full_id=static_cast<std::uint32_t>(actor_id);
      raw.values=ck3_12004::ReadWarPaymentGenericValues12004(
        bindings.current_raw_context_read?bindings.current_raw_context_read:&CurrentRawMemory,
        bindings.current_raw_context_read_context,raw.character);
      if(!ActorMatches(actor,actor_id))
        return FailActor(output,"war_cash_current_actor_changed_during_raw_context_read");
      raw.actor_identity_stable=true;
      output.current_raw_context=raw;

WarPaymentFrame12004 Capture(const WarPaymentBindings12004 &b, const WarPaymentRecord12004 &r) noexcept {
  WarPaymentFrame12004 f{};
  if (r.kind == WarPaymentKind12004::transition) {
    f.army_id = Read<std::uint32_t>(b,f,r.receiver,0x10);
    f.army_magic = Read<std::uint32_t>(b,f,r.receiver,0x14);
    f.requested_unit_id = Read<std::uint32_t>(b,f,r.receiver,0x124);
    f.army_1d4 = Read<std::uint8_t>(b,f,r.receiver,0x1D4);
    f.province_magic = Read<std::uint32_t>(b,f,r.second_pointer,0x85C);
    f.province_id = Read<std::uint32_t>(b,f,r.second_pointer,0x10);
  } else {
    f.character = r.kind == WarPaymentKind12004::gateway ? r.receiver : r.second_pointer;
    f.character_id = Read<std::uint32_t>(b,f,f.character,0x18);
    f.character_magic = Read<std::uint32_t>(b,f,f.character,0x1C);
    f.character_extension = Read<std::uintptr_t>(b,f,f.character,0x1B0);
    if (f.character_extension && *f.character_extension)
      f.personal_gold_bits = Read<std::uint64_t>(b,f,*f.character_extension,0x100);
    if (r.kind != WarPaymentKind12004::gateway) {
      f.wrapper = r.receiver;
      f.wrapper_balance_bits = Read<std::uint64_t>(b,f,f.wrapper,8);
      if (r.kind == WarPaymentKind12004::land_sub && f.wrapper >= 0x310) {
        f.land_id = Read<std::uint32_t>(b,f,f.wrapper-0x310,0x10);
        f.land_magic = Read<std::uint32_t>(b,f,f.wrapper-0x310,0x14);
      }
    }
  }
  f.capture_complete = f.failed_reads == 0;
  return f;

template<class Call> std::uintptr_t Invoke(const WarPaymentBindings12004 &b,
    WarPaymentRecord12004 &r, Call call) noexcept {
  if (!Ready(b)) return call();
  if (b.retain_actor && !b.retain_actor(b.retain_actor_context,r.kind,r.receiver,r.second_pointer))
    return call();
  army_observer_research_detail_12004::Permit permit(b.journal->mutex,b.journal->policy);
  if (!permit.admitted()) return call();
  Parent(r);
  r.entry_event = b.next_event(b.event_context);
  r.session_entry = b.session(b.session_context);
  r.natural_parent_metadata = Natural(b);
  r.before = Capture(b,r);
  if(r.kind==WarPaymentKind12004::gateway&&r.resource_kind_raw==4)
    r.resource4_wallet_context.emplace().before=Raw4Frame(b,r.before.character);
  if(b.generic_context_capture_enabled&&r.kind==WarPaymentKind12004::personal_add&&
      r.caller_return_rva==kWarPaymentGenericReturn12004) {
    auto &g=r.generic_wallet_context.emplace();
    g.before=ReadWarPaymentGenericValues12004(b.read,b.read_context,r.before.character);g.parent_trace=GenericParent(b);
    if(g.before.capture_complete) {
      const auto bits=static_cast<std::uint64_t>(*g.before.value_2c0)-
        static_cast<std::uint64_t>(*g.before.value_2c8)-
        (static_cast<std::uint64_t>(*g.before.value_28)+static_cast<std::uint64_t>(*g.before.value_30));
      g.before_computed_add_raw=std::bit_cast<std::int64_t>(bits);
      g.before_formula_matches_amount=*g.before_computed_add_raw==r.amount_raw;
    }
  }
  {
    Scope scope(r);
    r.original_called = true;
    r.raw_return_bits = call(); // exactly one original; no getter or replay
    r.original_returned = true;
  }
  r.after = Capture(b,r);
  if(r.resource4_wallet_context)
    r.resource4_wallet_context->after=Raw4Frame(b,r.after.character);
  if(r.generic_wallet_context) {
    auto &g=*r.generic_wallet_context;
    g.after=ReadWarPaymentGenericValues12004(b.read,b.read_context,r.after.character);
    g.context_values_stable=SameGenericValues(g.before,g.after);
  }
  r.session_return = b.session(b.session_context);
  r.natural_return_metadata = Natural(b);
  r.returned_event = b.next_event(b.event_context);

struct WarPaymentRecord12004 {
  // Retention ordinal only. Every cross-family join uses the shared event clock.
  std::uint64_t journal_sequence = 0;
  WarPaymentKind12004 kind = WarPaymentKind12004::transition;
  std::uintptr_t receiver = 0, second_pointer = 0, caller_return_rva = 0;
  std::int64_t amount_raw = 0;
  std::int32_t resource_kind_raw = -1, component_raw = -1;
  ArmyNaturalPhaseEvent12004 entry_event, returned_event;
  ArmyNaturalPhaseEvent12004 parent_transition_entry, parent_gateway_entry;
  std::uintptr_t parent_transition_army = 0, parent_gateway_character = 0;
  std::uintptr_t parent_transition_caller = 0, parent_gateway_caller = 0;
  std::int32_t parent_gateway_resource = -1, parent_gateway_component = -1;
  std::int64_t parent_gateway_amount = 0;
  WarPaymentNaturalParent12004 natural_parent_metadata;
  WarPaymentNaturalParent12004 natural_return_metadata;
  WarPaymentSession12004 session_entry, session_return;
  WarPaymentFrame12004 before, after;
  bool original_called = false, original_returned = false;
  std::uintptr_t raw_return_bits = 0;
  bool clock_thread_order_matches = false, session_matches = false;
  bool natural_parent_matches = false;
  bool same_character_after = false, same_wrapper_after = false;
  bool personal_wrapper_matches_character = false;
  bool source_boarding_call_chain_matches = false;
  bool tls_depth_exceeded = false;
  // Optional exact-caller raw inputs/parent frames; never military attribution.
  std::optional<WarPaymentGenericContext12004> generic_wallet_context;
  // Present only inside the existing gateway resource4 callback.
  std::optional<WarPaymentResource4WalletContext12004> resource4_wallet_context;

bool State(WarPaymentWindow12004 &w,std::uintptr_t &identity,std::uint64_t &date,std::uint32_t &day) noexcept {
  constexpr auto max=(std::numeric_limits<std::uintptr_t>::max)();
  return w.read&&w.module_base&&w.module_base<=max-0x5C68C50&&
    w.read(w.read_context,w.module_base+0x5C68C50,&identity,sizeof identity)&&identity&&identity<=max-0xA0&&
    w.read(w.read_context,identity+8,&date,sizeof date)&&w.read(w.read_context,identity+0x9C,&day,sizeof day);
}
void StopLocked(WarPaymentWindow12004 &w,std::string_view reason) {
  w.admitted=false;w.session.same_owned_process_no_load_window=false;
  w.session.controlled_window_id=0;w.reason=reason;
  if(w.journal)(void)w.journal->SetEnabled(false);
}
bool CheckLocked(WarPaymentWindow12004 &w) {
  if(!w.admitted)return false;
  if(!ReadArmyNaturalPhaseResearchSampling12004().enabled) {StopLocked(w,"natural_phase_sampling_disabled");return false;}
  std::uintptr_t state=0;std::uint64_t date=0;std::uint32_t day=0;
  if(!State(w,state,date,day)) {StopLocked(w,"game_state_read_failed");return false;}
  if(state!=w.session.game_state_identity_witness) {StopLocked(w,"game_state_identity_changed");return false;}
  if(w.session.native_date_raw&&static_cast<std::uint32_t>(date)<static_cast<std::uint32_t>(*w.session.native_date_raw)) {StopLocked(w,"native_date_rollback");return false;}
  if(w.session.absolute_day_raw&&day<*w.session.absolute_day_raw) {StopLocked(w,"absolute_day_rollback");return false;}
  w.session.native_date_raw=date;w.session.absolute_day_raw=day;return true;

WarPaymentSession12004 ReadWarPaymentWindowSession12004(void *context) noexcept {
  if(!context)return {};
  auto &w=*static_cast<WarPaymentWindow12004 *>(context);
  try {const std::lock_guard lock(w.mutex);(void)CheckLocked(w);return w.session;}catch(...) {return {};}
}
bool RetainWarPaymentWindowActor12004(void *context,WarPaymentKind12004 kind,std::uintptr_t receiver,std::uintptr_t second) noexcept {
  if(!context)return true;
  auto &w=*static_cast<WarPaymentWindow12004 *>(context);
  try {
    const std::lock_guard lock(w.mutex);if(!w.admitted)return false;
    // The transition's Army is retained without resolving native registries.
    // Gateway/leaf retain only the dynamically bound full-generation Character.
    if(kind==WarPaymentKind12004::transition)return true;
    const auto character=kind==WarPaymentKind12004::gateway?receiver:second;
    if(!character||character>(std::numeric_limits<std::uintptr_t>::max)()-0x20||!w.read)return true;
    std::uint32_t id=0,magic=0;
    if(!w.read(w.read_context,character+0x18,&id,sizeof id)||!w.read(w.read_context,character+0x1C,&magic,sizeof magic))return true;
    return magic!=0x43686172U||id==0xFFFFFFFFU||!w.session.player_character_full_id||id==*w.session.player_character_full_id;

if getattr(driver, "allow_private_war_cash_query", False) is True:
    @server.tool()
    def ck3_query_war_cash_current_resources_private_v1(
        expected_revision: int,
        payment_sampling: Literal["enable", "disable", "query"] | None = None,
        payment_window_contract: Literal["same_owned_process_no_load_v1"] | None = None,
    ) -> dict[str, object]:
        """Read cash and raw payment evidence; optional explicit observer gate control.

        Enable requires a paused same-process window without save/load, and
        natural-phase sampling already enabled. No gameplay payment is sent.
        """
        if payment_sampling is None and payment_window_contract is None:
            return driver.query_war_cash_current_resources_private_v1(expected_revision=expected_revision)
        return driver.query_war_cash_current_resources_private_v1(
            expected_revision=expected_revision, payment_sampling=payment_sampling,
            payment_window_contract=payment_window_contract)
